import com.hbm.tileentity.ModRBMKBlockEntities; import com.hbm.tileentity.machine.rbmk.*; import net.minecraft.core.BlockPos; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState;
public class RBMKControl extends RBMKBase { public final boolean moderated; public RBMKControl(Properties properties, boolean moderated) { super(properties); this.moderated = moderated; } @Override public boolean hasOwnLid() { return true; } @Override public int coreMask() { return this == ModRBMKBlocks.rbmk_control_reasim.get() ? MASK_DOWN : MASK_NONE; } @Override protected BlockEntityType<? extends BlockEntityRBMKBase> beType() { return ModRBMKBlockEntities.RBMK_CONTROL.get(); } @Override protected BlockEntityRBMKBase createCore(BlockPos pos, BlockState state) { return new BlockEntityRBMKControlManual(pos, state); } }
